join public.nfc_cards c on c.id = v.card_id
cross join lateral generate_series(c.activated_at::date, coalesce(c.deactivated_at::date, current_date), interval '1 day') as d(day)
cross join lateral (
  select round(l)::int as nfc, round(l * (0.32 + random() * 0.2))::int as qr
  from (select v.rate
          * (0.6 + 0.4 * (1 - (current_date - d.day::date) / 120.0))
          * (case extract(dow from d.day) when 0 then 1.45 when 6 then 1.45 when 5 then 1.2 else 1 end)
          * (0.7 + random() * 0.6) as l) x
) n
where n.nfc + n.qr > 0;

-- Recent raw events so card pages show a recent-activity feed.
select c.id, c.branch_id, c.business_id,
       (array['NFC_TAP','NFC_TAP','QR_SCAN','LANDING_PAGE_VIEW','GOOGLE_REVIEW_CLICK'])[1 + floor(random() * 5)::int]::public.event_type,
       now() - random() * interval '48 hours', 'demo', (array['mobile','mobile','mobile','tablet'])[1 + floor(random() * 4)::int],
       (array['Chrome','Safari','Safari','Samsung Internet'])[1 + floor(random() * 4)::int]
from public.nfc_cards c cross join generate_series(1, 6)
where c.status = 'active' and c.business_id is not null;

update public.nfc_cards c set last_used_at = x.last from (
  select card_id, max(created_at) as last from public.interaction_events group by card_id
) x where x.card_id = c.id;
update public.nfc_cards c set last_used_at = (x.day + time '18:00')::timestamptz from (
  select card_id, max(day) as day from public.card_daily_stats group by card_id
) x where x.card_id = c.id and c.last_used_at is null;


